fields.InputDefinition:
{
  "goal": "Assume you are already logged in at http://localhost:4200. Switch to the Admin application via the application switcher dropdown next to the logo, open 'Identity & Access', and select the 'Roles' sub-section. The list shows role cards, each with a type badge (System vs Custom) and Edit / Delete action buttons. Verify that for system roles the Edit and Delete buttons are disabled (not actionable), while custom roles have them enabled. Also expand a role card to confirm it reveals a stats section and a 'Permissions Preview' note. Success is observing the system-role action buttons being disabled and a card expanding. Pages can take 10-30s to load in this resource-constrained environment — wait, don't navigate away.",
  "startUrl": "http://localhost:4200",
  "allowedDomains": [
    "localhost",
    "*.auth0.com"
  ],
  "auth": {
    "bindings": [
      {
        "domains": [
          "localhost",
          "*.auth0.com"
        ],
        "method": {
          "Type": "Basic",
          "Username": "{{authUsername}}",
          "Password": "{{authPassword}}",
          "Strategy": "FormLogin"
        }
      }
    ]
  }
}
